<!-- Micro-Interactions Script -->
<script>
    function switchMainTab(tab) {
      const panelUsers = document.getElementById('panel-users');
      const panelEmployees = document.getElementById('panel-employees');
      const tabUsersBtn = document.getElementById('tab-users-btn');
      const tabEmployeesBtn = document.getElementById('tab-employees-btn');

      if (tab === 'users') {
        panelUsers.classList.remove('hidden');
        panelEmployees.classList.add('hidden');

        tabUsersBtn.className = "flex-1 sm:flex-none flex items-center justify-center gap-2.5 px-6 py-2.5 rounded-xl font-label-md text-label-md transition-all duration-200 bg-surface-container-lowest text-primary font-bold shadow-[0_4px_16px_rgba(91,77,255,0.12)]";
        tabEmployeesBtn.className = "flex-1 sm:flex-none flex items-center justify-center gap-2.5 px-6 py-2.5 rounded-xl font-label-md text-label-md transition-all duration-200 text-on-surface-variant hover:text-on-surface font-semibold";
      } else {
        panelUsers.classList.add('hidden');
        panelEmployees.classList.remove('hidden');

        tabEmployeesBtn.className = "flex-1 sm:flex-none flex items-center justify-center gap-2.5 px-6 py-2.5 rounded-xl font-label-md text-label-md transition-all duration-200 bg-surface-container-lowest text-primary font-bold shadow-[0_4px_16px_rgba(91,77,255,0.12)]";
        tabUsersBtn.className = "flex-1 sm:flex-none flex items-center justify-center gap-2.5 px-6 py-2.5 rounded-xl font-label-md text-label-md transition-all duration-200 text-on-surface-variant hover:text-on-surface font-semibold";
      }
    }

    function toggleModal(show) {
      const modal = document.getElementById('modal-container');
      if (show) {
        modal.classList.remove('hidden');
      } else {
        modal.classList.add('hidden');
      }
    }

    function toggleUserStatus(btn) {
      const dot = btn.querySelector('span');
      const isActive = btn.classList.contains('bg-secondary');
      if (isActive) {
        btn.classList.remove('bg-secondary');
        btn.classList.add('bg-surface-container-highest');
        dot.classList.remove('translate-x-4');
        dot.classList.add('translate-x-0');
      } else {
        btn.classList.remove('bg-surface-container-highest');
        btn.classList.add('bg-secondary');
        dot.classList.remove('translate-x-0');
        dot.classList.add('translate-x-4');
      }
    }

    function toggleCheckbox(btn) {
      const dot = btn.querySelector('span');
      const isActive = btn.classList.contains('bg-secondary');
      if (isActive) {
        btn.classList.remove('bg-secondary');
        btn.classList.add('bg-surface-container-highest');
        dot.classList.remove('translate-x-4');
        dot.classList.add('translate-x-0');
      } else {
        btn.classList.remove('bg-surface-container-highest');
        btn.classList.add('bg-secondary');
        dot.classList.remove('translate-x-0');
        dot.classList.add('translate-x-4');
      }
    }

    function generateRandomPass() {
      const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$";
      let res = "CK-";
      for (let i = 0; i < 8; i++) {
        res += chars.charAt(Math.floor(Math.random() * chars.length));
      }
      document.getElementById('password-input').value = res;
    }

    function copyPassword() {
      const pass = document.getElementById('password-input').value;
      navigator.clipboard.writeText(pass);
    }

    function openPinResetModal(name) {
      alert("Membuka dialog atur ulang PIN kasir untuk " + name + " (Verifikasi OTP Owner).");
    }

    function handleFormSubmit(e) {
      e.preventDefault();
      toggleModal(false);
    }
  </script>
